document.addEventListener('DOMContentLoaded', function() {
    const width = 700;
    const height = 700;
    const margin = { top: 20, right: 20, bottom: 20, left: 20 };

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height]);

    const tooltip = d3.select('#tooltip');

    d3.csv('data/stock-descriptions.csv').then(data => {
        // Clean data
        data.forEach(d => {
            d.ticker = d.ticker;
            d.name = d['full name'];
            d.sector = d.sector;
            d.marketCap = d.marketCap ? +d.marketCap : null;
            d.isETF = !d.marketCap;
        });

        // Determine sectors
        const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
        const colorScale = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        // Scale for radius
        const validMarketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);
        const minCap = d3.min(validMarketCaps);
        const maxCap = d3.max(validMarketCaps);

        const radiusScale = d3.scaleSqrt()
            .domain([minCap, maxCap])
            .range([10, 60]);

        const etfRadius = 20; // Uniform size for ETFs

        data.forEach(d => {
            d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
        });

        // Cluster centers
        const sectorCenters = {};
        const angleStep = (2 * Math.PI) / sectors.length;
        const orbitRadius = 200;
        sectors.forEach((sector, i) => {
            sectorCenters[sector] = {
                x: width / 2 + Math.cos(i * angleStep) * orbitRadius,
                y: height / 2 + Math.sin(i * angleStep) * orbitRadius
            };
        });

        // Simulation
        const simulation = d3.forceSimulation(data)
            .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.15))
            .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.15))
            .force('collide', d3.forceCollide(d => d.radius + 2))
            .force('center', d3.forceCenter(width / 2, height / 2))
            .stop();

        // Run simulation for fixed number of ticks for determinism
        for (let i = 0; i < 300; ++i) simulation.tick();

        // Draw bubbles
        const bubbles = svg.selectAll('.bubble-group')
            .data(data)
            .enter()
            .append('g')
            .attr('class', 'bubble-group')
            .attr('transform', d => `translate(${d.x},${d.y})`)
            .on('mouseover', function(event, d) {
                if (d.isETF) return;

                tooltip.classed('visible', true)
                    .html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>Sector: ${d.sector}`)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            })
            .on('mousemove', function(event) {
                tooltip.style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            })
            .on('mouseout', function() {
                tooltip.classed('visible', false);
            })
            .on('click', function(event, d) {
                highlightSelection(d.ticker);
            });

        bubbles.append('circle')
            .attr('class', 'bubble')
            .attr('id', d => `bubble-${d.ticker}`)
            .attr('r', d => d.radius)
            .attr('fill', d => colorScale(d.sector));

        bubbles.append('text')
            .attr('class', 'bubble-label')
            .attr('dy', '.3em')
            .text(d => d.ticker);

        // Legends
        const legendContainer = d3.select('#legend');
        sectors.forEach(sector => {
            const item = legendContainer.append('div').attr('class', 'legend-item');
            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', colorScale(sector));
            item.append('span').text(sector);
        });

        // Table
        const tableBody = d3.select('#stock-table tbody');
        const formatCap = d3.format('.2s');
        const formatLargeCap = (val) => {
            if (!val) return 'N/A';
            return formatCap(val).replace('G', 'B').replace('M', 'M').replace('T', 'T');
        };

        const rows = tableBody.selectAll('tr')
            .data(data.sort((a, b) => a.ticker.localeCompare(b.ticker)))
            .enter()
            .append('tr')
            .attr('id', d => `row-${d.ticker}`)
            .on('click', function(event, d) {
                highlightSelection(d.ticker);
            });

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d.name);
        rows.append('td').text(d => d.sector);
        rows.append('td').text(d => formatLargeCap(d.marketCap));

        function highlightSelection(ticker) {
            d3.selectAll('.bubble').classed('highlighted', false);
            d3.selectAll('tr').classed('highlighted', false);

            d3.select(`#bubble-${ticker}`).classed('highlighted', true);
            const selectedRow = d3.select(`#row-${ticker}`);
            selectedRow.classed('highlighted', true);

            // Scroll table to row
            const tableContainer = document.getElementById('table-container');
            const rowElement = document.getElementById(`row-${ticker}`);
            tableContainer.scrollTo({
                top: rowElement.offsetTop - tableContainer.offsetTop,
                behavior: 'smooth'
            });
        }
    });
});

